defmodule WorkbenchIgniter.Features.MailerTest do
  @moduledoc false

  use ExUnit.Case, async: true

  import Igniter.Test

  alias WorkbenchIgniter.PhxDelta

  # A project generated by phx.new without a mailer, held in memory.
  defp no_mailer_project, do: WorkbenchIgniter.TestProject.new(~w(--no-mailer))

  test "a --no-mailer project has no mailer, a default one has" do
    assert {false, _} = WorkbenchIgniter.Features.Mailer.installed?(no_mailer_project())
    assert {true, _} = WorkbenchIgniter.Features.Mailer.installed?(phx_test_project())
  end

  test "puts in what phx.new generates for a mailer" do
    igniter = no_mailer_project() |> Igniter.compose_task("workbench.install.mailer", [])

    igniter
    |> assert_creates("lib/test/mailer.ex", fn content -> assert content =~ "defmodule Test.Mailer do" end)
    |> assert_has_patch("mix.exs", """
    + | {:swoosh, "~> 1
    """)
    |> assert_has_patch("config/config.exs", """
    + | config :test, Test.Mailer, adapter: Swoosh.Adapters.Local
    """)

    assert igniter.issues == []
  end

  test "keeps the project's own edits to a file it changes" do
    igniter =
      no_mailer_project()
      |> Igniter.Project.MixProject.update(:project, [:version], fn _ -> {:ok, {:code, ~s("0.2.0")}} end)
      |> apply_igniter!()
      |> Igniter.compose_task("workbench.install.mailer", [])
      |> apply_igniter!()

    {facts, _} = PhxDelta.facts(igniter)
    assert facts.mailer
    mix = igniter.assigns[:test_files]["mix.exs"]
    assert mix =~ ~s|version: "0.2.0"|
    assert mix =~ ":swoosh"
  end

  test "reports a conflict and leaves the file alone, phx.new's version beside it" do
    # The project rewrote the very lines the mailer changes: the deps list.
    igniter =
      no_mailer_project()
      |> Igniter.update_file("mix.exs", fn source ->
        Rewrite.Source.update(source, :content, &String.replace(&1, ~r/defp deps do.*?\n  end/s, "defp deps do\n    [{:jason, \"~> 1.2\"}]\n  end"))
      end)
      |> apply_igniter!()
      |> Igniter.compose_task("workbench.install.mailer", [])

    assert Enum.any?(igniter.issues, &(&1 =~ "mix.exs: the mailer lines conflict"))
    assert_creates(igniter, "mix.exs.phx-new", fn content -> assert content =~ ":swoosh" end)
  end

  test "puts the new file where phx.new would, even when the app name carries digits" do
    # phx.new names lib/ and test/ after the app (lorem_ipsum_9), not
    # the module (lorem_ipsum9); Igniter would move the new module.
    igniter =
      WorkbenchIgniter.TestProject.new(~w(--app lorem_ipsum_9 --module LoremIpsum9 --database postgres --adapter bandit --no-mailer))
      |> Igniter.compose_task("workbench.install.mailer", [])
      |> apply_igniter!()

    files = igniter.assigns[:test_files]
    assert files["lib/lorem_ipsum_9/mailer.ex"] =~ "defmodule LoremIpsum9.Mailer do"
    refute Enum.any?(Map.keys(files), &String.contains?(&1, "lorem_ipsum9/"))
    assert files["lib/lorem_ipsum_9_web/router.ex"] =~ "Plug.Swoosh.MailboxPreview"
  end

  test "is a no-op with a notice when the mailer is in" do
    phx_test_project()
    |> Igniter.compose_task("workbench.install.mailer", [])
    |> assert_unchanged()
  end
end
